import{locateAnchor}from"/js/modules/Knowbase/CommentAnchor.js";import{buildDomTextIndex,wrapOffsetsInMarks}from"/js/modules/Knowbase/DomTextIndex.js";function clearHighlights(t){t.querySelectorAll("mark.kb-comment-highlight").forEach(t=>{const e=t.parentNode;while(t.firstChild){e.insertBefore(t.firstChild,t)}e.removeChild(t);e.normalize()})}export function highlightComments(t,e){clearHighlights(t);const o=[];if(!e||e.length===0){return o}for(const n of e){const e=buildDomTextIndex(t);const r=locateAnchor(e.text,n);if(!r){continue}const[i,s]=r;wrapOffsetsInMarks(e,i,s,n.id);o.push({id:String(n.id),text:e.text.slice(i,s)})}return o}